package com.hozefa.threepattipro.nativeapp;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;

public class VoiceRoundDraftTest {
    private Map<String,String> roster(){Map<String,String> r=new LinkedHashMap<>();r.put("h","Hozefa");r.put("a","Ali");r.put("b","Hussain");r.put("c","Ali Akbar");return r;}
    private VoiceRoundDraft draft(){return new VoiceRoundDraft(roster(),Arrays.asList("h","a","b"));}
    private VoiceRoundDraft ready(){VoiceRoundDraft d=draft();for(String answer:Arrays.asList("all players","Hozefa ne","170","Ali aur Hussain","hukum jeet gaya"))assertEquals(VoiceRoundDraft.Action.NEXT,d.answer(answer));assertEquals(VoiceRoundDraft.Step.REVIEW,d.step);return d;}
    private void rejectedBid(String value){try{VoiceRoundDraft.parseBid(value);fail(value);}catch(IllegalArgumentException expected){}}
    @Test public void completeConversationMatchesExistingScoring(){VoiceRoundDraft d=ready();assertEquals(ScoreRules.calculate(new ArrayList<>(d.players),170,"h",Arrays.asList("a","b"),"win"),d.scores());assertEquals(Integer.valueOf(340),d.scores().get("h"));}
    @Test public void onlyReviewAcceptsExplicitSave(){VoiceRoundDraft d=draft();assertEquals(VoiceRoundDraft.Action.RETRY,d.answer("save karo"));d=ready();assertEquals(VoiceRoundDraft.Action.RETRY,d.answer("haan"));assertEquals(VoiceRoundDraft.Action.SAVE,d.answer("save karo"));}
    @Test public void cancelNeverCompletesASave(){VoiceRoundDraft d=ready();assertEquals(VoiceRoundDraft.Action.CANCEL,d.answer("cancel karo"));}
    @Test public void previousPlayersAreFilteredToActiveRoster(){VoiceRoundDraft d=new VoiceRoundDraft(roster(),Arrays.asList("h","a","b","removed"));assertEquals(VoiceRoundDraft.Action.NEXT,d.answer("pichhle wale players"));assertEquals(new LinkedHashSet<>(Arrays.asList("h","a","b")),d.players);}
    @Test public void missingPreviousDoesNotInventPlayers(){VoiceRoundDraft d=new VoiceRoundDraft(roster(),Collections.emptyList());assertEquals(VoiceRoundDraft.Action.RETRY,d.answer("previous players"));assertEquals(VoiceRoundDraft.Step.PLAYERS,d.step);}
    @Test public void partialOrUnknownNamesAreRejectedAtomically(){VoiceRoundDraft d=draft();assertEquals(VoiceRoundDraft.Action.RETRY,d.answer("Hozefa Ali mystery"));assertTrue(d.players.isEmpty());assertEquals(VoiceRoundDraft.Action.RETRY,d.answer("Hozef Ali Hussain"));}
    @Test public void fullNamesBeatTheirShorterPrefixes(){VoiceRoundDraft d=draft();d.answer("Hozefa Hussain Ali Akbar");assertTrue(d.players.contains("c"));assertFalse(d.players.contains("a"));}
    @Test public void duplicateNamesNeedPlayerNumbers(){Map<String,String> r=roster();r.put("b","Ali");VoiceRoundDraft d=new VoiceRoundDraft(r,Collections.emptyList());assertEquals(VoiceRoundDraft.Action.RETRY,d.answer("Hozefa Ali Ali Akbar"));assertEquals(VoiceRoundDraft.Action.NEXT,d.answer("1 2 3 4"));d.answer("number three");assertEquals("b",d.hukum);}
    @Test public void hindiNumbersAndDigitsResolveDisplayedRosterOrder(){VoiceRoundDraft d=draft();assertEquals(VoiceRoundDraft.Action.NEXT,d.answer("प्लेयर एक दो तीन"));d.answer("नंबर १");assertEquals("h",d.hukum);}
    @Test public void inactiveOrUnselectedHukumCannotEnterRound(){VoiceRoundDraft d=draft();d.answer("1 2 3");assertEquals(VoiceRoundDraft.Action.RETRY,d.answer("Ali Akbar"));assertNull(d.hukum);}
    @Test public void hukumCannotAlsoBePartner(){VoiceRoundDraft d=draft();d.answer("all");d.answer("Hozefa");d.answer("170");assertEquals(VoiceRoundDraft.Action.RETRY,d.answer("Hozefa Ali"));assertTrue(d.partners.isEmpty());}
    @Test public void noPartnerCannotBypassExistingRules(){VoiceRoundDraft d=draft();d.answer("all");d.answer("1");d.answer("170");assertEquals(VoiceRoundDraft.Action.RETRY,d.answer("koi partner nahi"));}
    @Test public void atLeastOneOpponentIsRequired(){VoiceRoundDraft d=draft();d.answer("1 2 3");d.answer("1");d.answer("170");assertEquals(VoiceRoundDraft.Action.RETRY,d.answer("2 3"));}
    @Test public void repeatedPartnerNamesCountOnce(){VoiceRoundDraft d=draft();d.answer("1 2 3");d.answer("1");d.answer("170");assertEquals(VoiceRoundDraft.Action.NEXT,d.answer("Ali aur Ali"));assertEquals(1,d.partners.size());}
    @Test public void negativeOrMixedOutcomeIsNotGuessed(){VoiceRoundDraft d=ready();d.answer("result badlo");assertEquals(VoiceRoundDraft.Action.RETRY,d.answer("not win"));assertEquals(VoiceRoundDraft.Action.RETRY,d.answer("win or loss"));assertEquals(VoiceRoundDraft.Step.RESULT,d.step);}
    @Test public void hindiLossUsesOriginalOddBidRounding(){VoiceRoundDraft d=ready();d.answer("bid badlo");d.answer("155");d.answer("Ali");d.answer("हुकुम हार गया");assertEquals(Integer.valueOf(-155),d.scores().get("h"));assertEquals(Integer.valueOf(-78),d.scores().get("a"));assertEquals(Integer.valueOf(155),d.scores().get("b"));}
    @Test public void editCommandsAndBackRemainInsideDraft(){VoiceRoundDraft d=ready();d.answer("bid badlo");assertEquals(VoiceRoundDraft.Step.BID,d.step);d.answer("200");assertEquals(VoiceRoundDraft.Step.PARTNERS,d.step);d.back();assertEquals(VoiceRoundDraft.Step.BID,d.step);assertEquals(200,d.bid);}
    @Test public void changingPlayersInvalidatesDependentSelections(){VoiceRoundDraft d=ready();d.answer("players badlo");d.answer("1 2 3");assertNull(d.hukum);assertNull(d.result);assertTrue(d.partners.isEmpty());}
    @Test public void cannotSkipPlayerSelectionUsingEditCommand(){VoiceRoundDraft d=draft();assertEquals(VoiceRoundDraft.Action.RETRY,d.answer("bid badlo"));assertEquals(VoiceRoundDraft.Step.PLAYERS,d.step);}
    @Test public void numericBidRangeMatchesManualPicker(){for(int n=155;n<=250;n+=5)assertEquals(n,VoiceRoundDraft.parseBid(String.valueOf(n)));for(String s:Arrays.asList("150","255","171","-170","170 180","170.5","seventeen",""))rejectedBid(s);}
    @Test public void spokenEnglishBidsSupportIndianAndFullForms(){assertEquals(170,VoiceRoundDraft.parseBid("one seventy"));assertEquals(155,VoiceRoundDraft.parseBid("one hundred and fifty five"));assertEquals(250,VoiceRoundDraft.parseBid("two fifty"));assertEquals(200,VoiceRoundDraft.parseBid("two hundred"));assertEquals(170,VoiceRoundDraft.parseBid("bid one seventy points"));}
    @Test public void hindiBidsSupportWordsAndDevanagariDigits(){assertEquals(170,VoiceRoundDraft.parseBid("एक सौ सत्तर"));assertEquals(155,VoiceRoundDraft.parseBid("एक सौ पचपन"));assertEquals(250,VoiceRoundDraft.parseBid("ढाई सौ"));assertEquals(170,VoiceRoundDraft.parseBid("१७०"));}
    @Test public void malformedNumberPhrasesNeverBecomeAValidBid(){for(String s:Arrays.asList("one one fifty three","one hundred hundred seventy","two and fifty","one seventy five five","one seventy and","-170","170.0"))rejectedBid(s);}
    @Test public void restoreKeepsNumberingAndNeverEmitsSave(){VoiceRoundDraft d=ready(),copy=VoiceRoundDraft.decode(d.encode());assertEquals(new ArrayList<>(d.roster.keySet()),new ArrayList<>(copy.roster.keySet()));assertEquals(VoiceRoundDraft.Step.REVIEW,copy.step);assertEquals(d.scores(),copy.scores());assertEquals(VoiceRoundDraft.Action.RETRY,copy.answer("yes"));}
    @Test public void everyStepRoundTripsAcrossRecreation(){VoiceRoundDraft d=draft();for(String text:Arrays.asList("all","1","170","2","win")){d=VoiceRoundDraft.decode(d.encode());d.answer(text);}assertEquals(VoiceRoundDraft.Step.REVIEW,d.step);assertEquals(VoiceRoundDraft.Action.SAVE,d.answer("सेव करो"));}
    @Test public void malformedRestorationIsRejected(){try{VoiceRoundDraft.decode("{}");fail();}catch(IllegalArgumentException expected){}}
    @Test public void tooLongAndNullAnswersAreSafe(){VoiceRoundDraft d=draft();assertEquals(VoiceRoundDraft.Action.RETRY,d.answer(null));assertEquals(VoiceRoundDraft.Action.RETRY,d.answer(new String(new char[600]).replace('\0','a')));assertTrue(d.players.isEmpty());}
    @Test public void correctionRequiresReconfirmingPreview(){VoiceRoundDraft d=ready();d.answer("bid badlo");assertEquals(VoiceRoundDraft.Action.RETRY,d.answer("save karo"));assertEquals(170,d.bid);}
}
